<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Как подписать отчёт в «Электронном бюджете» по соглашению?", "acceptedAnswer": {"@type": "Answer", "text": "Открыть сформированный отчёт в карточке соглашения под пользователем с ролью утверждения, проверить данные и подписать квалифицированным сертификатом. Система сама ставит отметку об электронной подписи и фиксирует дату представления. Представитель подписывает только при привязанной машиночитаемой доверенности."}}, {"@type": "Question", "name": "Как отправить отчёт в «Электронном бюджете» распорядителю?", "acceptedAnswer": {"@type": "Answer", "text": "После подписания отчёт направляется распорядителю из той же карточки; статус документа меняется в реестре. Отдельное письмо или бумажный экземпляр не требуются и не заменяют отправку в системе (п. 31 Правил № 1780)."}}, {"@type": "Question", "name": "Как создать отчёт в «Электронном бюджете» по соглашению, если соглашения нет в реестре?", "acceptedAnswer": {"@type": "Answer", "text": "Никак: отчёт формируется только из зарегистрированного соглашения. Если соглашение подписано, но не отображается, проверьте полномочия пользователя и завершение регистрации распорядителем — до этого срок отчёта считать рано, но и подписание затягивать нельзя."}}, {"@type": "Question", "name": "Как заполнить отчёт о достижении значений результатов предоставления субсидии, если результат ещё не наступил?", "acceptedAnswer": {"@type": "Answer", "text": "Показать фактическое значение «0» или достигнутую часть нарастающим итогом, указать отклонение и его причину с ожидаемой датой. Параллельно в отчёте о плане мероприятий отразить контрольные точки, запланированные на ближайшие три месяца, с признаком наличия или отсутствия отклонений."}}, {"@type": "Question", "name": "Какой срок сдачи отчёта по соглашению о субсидии?", "acceptedAnswer": {"@type": "Answer", "text": "Не реже раза в квартал, не позднее 10-го рабочего дня месяца после отчётного квартала (п. 29 Правил № 1780); при сроке результата больше 12 месяцев — не реже раза в год, не позднее 10-го рабочего дня января (п. 35). Соглашение может задать более короткий срок в пункте 4.3.17."}}, {"@type": "Question", "name": "Сколько распорядитель проверяет отчёт?", "acceptedAnswer": {"@type": "Answer", "text": "До 30 рабочих дней (п. 33), до 20 — для единовременного возмещения затрат (п. 30), до 60 — для возмещения недополученных доходов, объединённой субсидии, субсидий с «иными лицами» и с более чем пятью характеристиками результата (п. 34)."}}, {"@type": "Question", "name": "Что такое отчёт о реализации плана мероприятий и обязателен ли он?", "acceptedAnswer": {"@type": "Answer", "text": "Это отчёт о контрольных точках по приложению № 3 к Порядку № 53н. Обязателен, если в соглашении есть план мероприятий и мониторинг (п. 4.1.6.2 типовой формы); не проводится для единовременного возмещения затрат при уже достигнутом результате."}}, {"@type": "Question", "name": "Как добавить отметку об электронной подписи на отчёт?", "acceptedAnswer": {"@type": "Answer", "text": "Отметка формируется системой при подписании и попадает в печатную форму, выгруженную после подписания. Ставить её вручную или подписывать выгруженный файл сторонней программой не нужно — такую подпись система не учтёт."}}, {"@type": "Question", "name": "Как добавить полномочия сотруднику, чтобы он мог сдавать отчёты?", "acceptedAnswer": {"@type": "Answer", "text": "Подать заявку на регистрацию уполномоченного лица организации с ролями ввода и утверждения по реестру соглашений; для сотрудника, который не руководитель, — оформить машиночитаемую доверенность с полномочием подписания отчётности по соглашениям."}}, {"@type": "Question", "name": "Отчёт по соглашению и отчёт о расходах целевых средств для казначейства — это одно и то же?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Отчёт по соглашению сдаётся распорядителю по формам типового соглашения; отчёт о расходах целевых средств — территориальному органу Федерального казначейства по Порядку № 214н. При субсидии под казначейским сопровождением сдаются оба."}}, {"@type": "Question", "name": "Можно ли исправить уже отправленный отчёт?", "acceptedAnswer": {"@type": "Answer", "text": "Да, уточнённым отчётом с видом документа «1» после возврата распорядителем с замечаниями или по собственной инициативе до принятия. Срок проверки распорядителем по уточнённому отчёту исчисляется заново."}}, {"@type": "Question", "name": "Что будет, если не сдать отчёт в срок?", "acceptedAnswer": {"@type": "Answer", "text": "Это нарушение условий соглашения: распорядитель направляет претензию, при недостижении результатов — требование о возврате, при нарушении условий — требование о штрафных санкциях (пп. 4.1.9–4.1.11 типовой формы). Возможна ответственность по статье 15.15.5 КоАП РФ."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Как создать, подписать и отправить отчёт по соглашению о субсидии в «Электронном бюджете»", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Проверить доступ и роль пользователя", "text": "Войти в личный кабинет получателя по квалифицированному сертификату; у сотрудника, который будет формировать отчёт, должна быть роль ввода данных, у подписанта — роль утверждения. Полномочия назначаются через заявку на регистрацию уполномоченных лиц организации и подтверждаются машиночитаемой доверенностью, если подписывает не руководитель. Как подключиться и что делать, если система не видит серт"}, {"@type": "HowToStep", "position": 2, "name": "Открыть соглашение в реестре и перейти к отчётам", "text": "В реестре соглашений получатель видит только свои документы. В карточке зарегистрированного соглашения есть раздел отчётности, где по каждому виду отчёта заведён свой список. Если соглашение ещё не зарегистрировано распорядителем, отчёт создать нельзя — сначала завершите подписание, порядок описан в статье о соглашении о предоставлении субсидии."}, {"@type": "HowToStep", "position": 3, "name": "Создать отчёт нужного вида и выбрать период", "text": "Выберите вид отчёта — о достижении значений результатов, о расходах или о реализации плана мероприятий — и отчётный период. Система проставит «по состоянию на 1 ___ 20__ г.», периодичность (месячная, квартальная, годовая) и вид документа «0» — первичный. Уточнённый отчёт получит «1», «2» и далее; этот признак заложен в шапку приложения № 7."}, {"@type": "HowToStep", "position": 4, "name": "Заполнить раздел о результатах", "text": "Плановые значения и направления расходов подтягиваются из соглашения и не редактируются. Вносятся фактические значения — с даты заключения соглашения и отдельно с начала текущего финансового года, — а система считает отклонение в абсолютных величинах и в процентах. По каждой строке с отклонением заполняется причина: код и наименование из справочника. Отдельная графа — объём денежных обязательств, "}, {"@type": "HowToStep", "position": 5, "name": "Заполнить отчёт о расходах и приложить подтверждения", "text": "В отчёте о расходах по каждому направлению указываются плановый объём, кассовые расходы за период и с начала года, остаток. Если субсидия под казначейским сопровождением, цифры должны биться с выпиской по лицевому счёту 71 и со сведениями об операциях с целевыми средствами — расхождение здесь чаще всего становится причиной отклонения отчёта. Подтверждающие документы прикладываются файлами, если эт"}, {"@type": "HowToStep", "position": 6, "name": "Подписать отчёт усиленной квалифицированной подписью", "text": "Сформированный отчёт отправляется на утверждение внутри организации: подписант открывает документ, проверяет и подписывает сертификатом. Система ставит отметку об электронной подписи и фиксирует время — именно эта дата считается датой представления отчёта. Подписант без роли утверждения кнопку подписи не увидит; это самая частая причина «пропавшего» срока в последний день."}, {"@type": "HowToStep", "position": 7, "name": "Отправить распорядителю и отследить статус", "text": "После подписания отчёт направляется распорядителю и меняет статус в реестре. Распорядитель либо принимает документ, либо возвращает с замечаниями — тогда формируется уточнённый отчёт с видом документа «1». Скриншот или выгрузка отчёта со статусом «принят» — то, что стоит хранить вместе с пакетом по субсидии: он подтверждает исполнение обязанности в срок."}]}
</script>
