{"@context": "https://schema.org", "@type": "DefinedTermSet", "name": "Термины: отчёт по соглашению о субсидии", "inLanguage": "ru-RU", "hasDefinedTerm": [{"@type": "DefinedTerm", "name": "Отчёт о достижении значений результатов предоставления субсидии", "description": "отчёт по приложению № 7 к типовой форме № 199н: плановые и фактические значения результатов и характеристик, отклонения, причины, принятые обязательства."}, {"@type": "DefinedTerm", "name": "Отчёт об осуществлении расходов", "description": "отчёт по приложению № 10 к типовой форме о кассовых расходах по направлениям, источник которых — субсидия; сдаётся при финансовом обеспечении затрат."}, {"@type": "DefinedTerm", "name": "Контрольная точка", "description": "событие, отражающее завершение мероприятия по получению результата; тип контрольной точки берётся из приложения № 1 к Порядку № 53н."}, {"@type": "DefinedTerm", "name": "План мероприятий", "description": "документ распорядителя с контрольными точками по каждому результату, не менее одной в квартал; утверждается вместе с соглашением."}, {"@type": "DefinedTerm", "name": "Вид документа", "description": "признак в шапке отчёта: «0» — первичный, «1», «2» и далее — уточнённые отчёты после замечаний."}, {"@type": "DefinedTerm", "name": "Акт об исполнении обязательств", "description": "документ распорядителя по пункту 4.1.12 соглашения, направляемый после принятия всех отчётов и закрывающий соглашение."}, {"@type": "DefinedTerm", "name": "Роль утверждения", "description": "полномочие пользователя в «Электронном бюджете», позволяющее подписать и отправить документ; назначается заявкой на регистрацию уполномоченных лиц."}]}
